window.DAILY = {"generated_utc": "2026-09-09T05:20:18Z", "date_cn": "2026-09-09", "window_days": 3, "source": "arXiv API (cs.CV/cs.RO) · 热度加成: Hugging Face Daily Papers", "note": "所有条目直接来自 arXiv 元数据，未经人工或模型改写；预印本未经同行评审。", "tracks": {"slam": {"name": "SLAM 与状态估计", "papers": [{"id": "2609.07497", "title": "Functional-SLAM: Interaction-Aware Mapping with Online Functional Scene Graphs", "authors": ["Xinggang Hu", "Chenyangguang Zhang", "Zihan Zhu", "Ruida Zhang", "Xiangkui Zhang", "Xiangyang Ji"], "abstract": "Existing SLAM systems lack modeling of the functional relations required for fine-grained robotic interaction. Functional 3D scene graphs can represent relations between objects and interaction elements, but existing methods rely on offline reconstruction, making them inadequate for real-time interaction in real-world exploration. To address this limitation, we propose Functional-SLAM, the first framework that continuously and recursively maintains a functional scene graph as an online SLAM state. The framework combines anchor-keyframe geometry with functional-context constraints for persistent node maintenance, accumulates multi-frame evidence through temporal relations to commit stable functional edges, and supplements visual loop-closure candidates with functional topology in scenes with repetitive appearance or degraded texture. Experiments show that Functional-SLAM efficiently constructs stable functional maps online, substantially improving runtime over offline methods while maintaining highly competitive accuracy. Compared with peer SLAM systems, it further improves pose estimation accuracy through functional-topology-assisted loop closure. The code is publicly available at https://github.com/Hbelief1998/Functional-SLAM-CoRL_2026.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07497", "summary": "针对SLAM缺少交互功能关系建模、功能场景图依赖离线重建的问题，提出首个以功能场景图为在线SLAM状态的Functional-SLAM：用关键帧几何与功能上下文约束维护节点，经时间关系积累证据确定稳定功能边，并以功能拓扑辅助回环。其在线构建稳定功能图，运行时间较离线方法大幅缩短且精度具竞争力，还提升位姿估计精度。"}, {"id": "2609.07274", "title": "LightSplat: Real-Time High-Fidelity 3D Gaussian SLAM with Loop Closure", "authors": ["Junze Bao", "Ye Gao", "Yiming Huang", "Xiaolong Yu", "Chen Dong", "Qing Gao", "Wei Wang", "Jinhu Lü"], "abstract": "SLAM systems based on 3D Gaussian Splatting (3DGS) have recently demonstrated promising reconstruction accuracy for dense 3D scene representations. However, current 3DGS systems struggle to meet the strict demands of real-world deployments due to severe limitations in operational performance and map adaptability. To this end, we propose LightSplat, a hybrid-representation RGB-D SLAM framework. It synergizes local sparse features for robust and fast tracking with a dual-thread backend that progressively constructs dense Gaussian submaps. Crucially, we enable online loop closure through feature-accelerated 3DGS registration, refining overall map consistency through pose graph optimization. Ultimately, LightSplat achieves the online reconstruction of high-fidelity Gaussian map. Extensive experiments on multiple datasets and real-world robotic platform demonstrate that our method achieves near state-of-the-art reconstruction quality and the capability to accommodate practical camera motions, maintaining an average framerate of 8 FPS. Overall, LightSplat provides an efficient and robust foundation for deploying high-fidelity 3DGS in real-world environments.", "published": "2026-09-07", "comment": "Accepted to 2026 IEEE/RSJ International Conference on Intelligent Robots and Systems (IROS)", "url": "https://arxiv.org/abs/2609.07274", "summary": "针对3DGS SLAM难以满足真实部署对运行性能与地图适应性要求的问题，提出混合表示RGB-D SLAM框架LightSplat：以局部稀疏特征实现快速鲁棒跟踪，双线程后端渐进构建稠密高斯子图，并经特征加速的3DGS配准实现在线回环与位姿图优化。多数据集与真实机器人平台实验显示其重建质量接近SOTA、能适应实际相机运动，平均帧率8 FPS。"}, {"id": "2609.08626", "title": "MFVINS: Multiple Fisheye Camera-Based Visual Inertial System", "authors": ["Eunseong Jang", "YuJin Chung", "Sang Jun Lee", "Jihyun Yoon", "HyungGi Jo"], "abstract": "A simultaneous localization and mapping (SLAM) method using a monocular camera and a low-cost inertial measurement unit (IMU) sensor is an effective way to fulfill a low-cost sensor configuration. Using this sensor configuration, visual-inertial system (VINS) focuses on fusing data from a camera and an IMU sensor to estimate the six degrees-of-freedom (DOF) of the sensor pose. Typically, VINS uses only a single camera as visual input, which lead to problems such as error accumulation due to occlusion, various illumination, and textureless environments. In this paper, we propose a new multiple fisheye camera-based visual-inertial system called MFVINS. We present an IMU-aided FAST feature tracker for multiple cameras that enables efficient extraction and robust matching of local features. Then, the proposed method filters out outliers caused by fisheye distortion on the normalized image plane. Subsequently, a new reprojection error with physical validity constraints is proposed for bundle adjustment using learning-based depth estimation. The proposed method is applied to various scenarios, and its effectiveness is demonstrated by comparing previous VINS methods. In particular, MFVINS is implemented in real-time process to leverage the advantages of using multiple cameras -- robustness against occlusion and textureless regions -- while reducing the computational burden.", "published": "2026-09-08", "comment": "29 pages, 11 figures", "url": "https://arxiv.org/abs/2609.08626", "summary": "针对单相机VINS在遮挡、光照变化和无纹理环境下误差累积的问题，提出多鱼眼相机视觉惯性系统MFVINS：含IMU辅助多相机特征跟踪、归一化像平面畸变外点滤除，以及面向学习深度估计、带物理有效性约束的重投影误差用于捆绑调整。其实时运行，多场景对比验证其有效性，兼具多相机鲁棒性与更低计算负担。"}, {"id": "2609.08013", "title": "A Black-Box Adversarial Attack on Human Pose Estimation and Keypoint-Based Action Recognition Models", "authors": ["Kacper Mroczek", "Michal Kepski"], "abstract": "Human pose estimation and keypoint-based action recognition models are increasingly deployed as components of video understanding pipelines, yet their vulnerability to adversarial attacks remains insufficiently studied. Temporally coherent black-box attacks have been previously studied in visual object tracking, where the attack feedback can be defined using bounding-box overlap measures such as Intersection over Union (IoU). However, human pose estimation produces keypoint configurations rather than enclosing boxes, making box-level similarity poorly suited for measuring pose degradation. We propose OKS Attack, a decision-based black-box attack that uses Object Keypoint Similarity (OKS) as the attack feedback signal, directly targeting the spatial structure of human poses rather than their enclosing boxes. Experiments on the Penn Action dataset show that OKS Attack consistently reduces pose quality across evaluated pose estimators, with mean OKS decreases ranging from 0.0802 to 0.1494. In a downstream cross-dataset action-recognition evaluation, the attack reduces accuracy by 6.18 to 13.86 percentage points and outperforms query-matched random-noise perturbations. The attack is effective across both top-down and single-stage pose estimation models. The source code will be made publicly available at https://github.com/KacperM33/OKS_attack", "published": "2026-09-07", "comment": "Accepted at ACIVS2026", "url": "https://arxiv.org/abs/2609.08013", "summary": "针对姿态估计与动作识别模型脆弱性研究不足、框级相似度难以度量姿态退化的问题，提出决策式黑盒攻击OKS Attack，以OKS为反馈信号直接攻击姿态空间结构。Penn Action实验显示其持续降低各姿态估计器质量（平均OKS降0.0802至0.1494），使跨数据集动作识别精度下降6.18至13.86个百分点，优于查询量匹配的随机噪声，对两类姿态模型均有效。"}, {"id": "2609.07116", "title": "MAC-I$^2$: Learned Metrics-Aware Covariance for Robust Visual-Inertial Fusion in Initialization and Calibration", "authors": ["Xiang Fei", "Yuheng Qiu", "Can Xu", "Yutian Chen", "Ruogu Li", "Xingxing Zuo", "Wenshan Wang", "Sebastian Scherer"], "abstract": "Visual-Inertial (VI) fusion is fundamental to accurate and robust state estimation, where camera and IMU measurements are combined according to their respective uncertainties. Existing methods, however, fuse the two modalities with predefined uncertainties, regardless of how reliable each is in the local context, and thus often struggle under challenging environments involving illumination changes, dynamic objects, and textureless regions. In this paper, we present MAC-I$^2$, which achieves robust VI fusion through learned metric-aware covariance for both modalities, so that vision and IMU compete on their own merits rather than relying on predefined uncertainties. Here, metrics-aware means that each predicted covariance faithfully reflects the actual magnitude of the corresponding measurement noise. On the visual side, we propagate learned feature-matching uncertainties into pose covariances for the fusion. On the inertial side, motivated by the observation that integration error accumulates sharply at the early stage and grows slowly afterward, we design a learned IMU model with a learnable initial covariance, and propose a dedicated fine-tuning strategy on a held-out training subset to enable the metrics-aware covariance on unseen sequences. As a showcase, we build a VI initialization and calibration system, since accurate and robust initialization and calibration are the prerequisite for any reliable VI system. Experiments on EuRoC, and VBR show that MAC-I$^2$ substantially outperforms existing methods: it achieves a 99.9% initialization success rate on EuRoC, reducing gravity and velocity errors by about 60% and 42% over the strongest baseline, and maintains 80% success rate on challenging VBR sequences where baseline methods such as VINS-Mono drop below 10%.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07116", "summary": "针对视觉惯性融合沿用预定义不确定性、难以适应动态干扰的问题，提出MAC-I2：为视觉与IMU学习度量感知协方差，视觉侧将特征匹配不确定性传播为位姿协方差，IMU侧用可学习初始协方差与微调策略，并构建VI初始化标定系统。EuRoC上初始化成功率达99.9%，重力和速度误差较最强基线约降60%和42%，困难VBR序列上保持80%成功率。"}, {"id": "2609.07091", "title": "Human-Aware Target Tracking and Navigation: Fusing Kinematic State Estimation with Structural Map Constraints", "authors": ["Sagar Gupta", "Don Gideon", "Seng W. Loke", "Kevin Lee", "Bijo Sebastian"], "abstract": "Autonomous mobile robots performing person-following tasks often suffer from temporary occlusions and sensor track loss in dynamic environments. This research presents an end-to-end autonomous navigation stack that addresses target occlusion through map-informed spatial reasoning. The proposed system features a multi-modal perception pipeline, fusing deep learning-based visual tracking with 2-dimensional LiDAR point clustering to maintain high-fidelity tracking of a tagged person. A continuous state estimator integrates this perception data with wheel odometry and IMU sensors for stable localization. When the active track is lost due to occlusion, the system activates a map-based recovery framework. Leveraging a predefined topological map, the system executes a graph-based search to propagate the target's last known trajectory along structurally defined walking lanes, adhering to left-hand regional conventions. By generating a discrete set of feasible future trajectories, the robot reasons about potential structural trajectory changes, such as continuing a heading or turning at an intersection. This map-informed prediction is fed directly to the local obstacle avoidance planner, enabling the robot to continue following its target safely and predictably until the person is visually reacquired. Real-world evaluations in dense multi-person environments demonstrate the system's robustness, achieving a 71.4\\% target reacquisition success rate during major occlusion events lasting up to 7 seconds.", "published": "2026-09-07", "comment": "Submitted to Australian Conference on Robotics and Automation", "url": "https://arxiv.org/abs/2609.07091", "summary": "针对人跟随机器人因遮挡丢失目标的问题，提出端到端导航栈：融合深度学习视觉跟踪与2D LiDAR点聚类，连续状态估计器融合轮式里程计与IMU；跟踪丢失时基于预定义拓扑地图做图搜索，沿步行通道传播目标轨迹并生成可行未来轨迹供避障规划。真实密集多人群环境中，最长7秒的大遮挡下目标重获成功率达71.4%。"}, {"id": "2609.06820", "title": "Diagnosing and Dynamically Filtering Occupancy World Models for Active Mapping", "authors": ["Jiahui Zhang", "Gongbo Liang", "Yu Zhang"], "abstract": "Active mapping requires a robot to select camera viewpoints that efficiently reconstruct an unknown 3D scene. To reason about unobserved regions, recent systems use pretrained occupancy networks as world models that complete missing geometry. The predicted structure contributes to expected coverage gain and constrains feasible robot motion. Consequently, occupancy errors can change both what the robot chooses to explore and where it is able to move. We diagnose these effects by holding the planner fixed and varying only the occupancy representation provided to it. We consider planning without completion, with learned occupancy, with false positives removed by a ground truth oracle, with false negatives restored by an oracle, and with ground truth occupancy. Our experiments show that correcting false positives or false negatives alone does not consistently improve final coverage. This finding reveals a gap between occupancy accuracy and downstream planning performance. Ground truth occupancy provides a much larger improvement in coverage efficiency than in endpoint coverage, suggesting that planning and reachability remain important bottlenecks even when the geometric world model is accurate. Based on these findings, we introduce a dynamic filtering strategy that preserves predictions in unexplored space while suppressing repeatedly unsupported occupancy using online observations. Preliminary examples show that this strategy can redirect viewpoint selection toward reachable surfaces that would otherwise remain unobserved.", "published": "2026-09-06", "comment": "Accepted by IEEE IROS 2026 Workshop on WORLDS: World Models and Spatial Intelligence for Physical AI", "url": "https://arxiv.org/abs/2609.06820", "summary": "占用世界模型误差会影响主动映射的探索选择与可达性。固定规划器、更换占用表示的诊断表明，仅纠正假阳性或假阴性不能一致提升覆盖，揭示占用精度与规划性能的差距。据此提出动态过滤策略，保留未探索空间预测、抑制反复无支撑的占用，初步示例显示其可把视角引向原本不可见的可达表面。"}, {"id": "2609.06726", "title": "Back to the Feature: Zero-Shot 6DoF Pose Estimation via Dense Local Features", "authors": ["Ali Rafiaei", "Michael Greenspan"], "abstract": "We present B2TFPose, a training-free zero-shot method for 6DoF pose estimation of unseen objects from RGB images. Using a single frozen DINOv3 vision transformer as its only pretrained component within the pose estimation pipeline, B2TFPose extracts dense patch-level features that generalize across the synthetic-to-real domain gap without any task-specific fine-tuning, revisiting the classical local feature matching paradigm through the lens of large-scale self-supervised foundation models. Three contributions advance the training-free state of the art. A geodesic non-maximum suppression strategy retrieves a viewpoint-diverse template set for coarse-to-fine correspondence matching. Render-guided Re-Correspondence (RRC) synthesizes object-specific views at the estimated pose and re-establishes dense 2D-3D correspondences to sharpen the initial estimate without additional learned parameters. A multi-mask hypothesis selection strategy jointly scores competing segmentation candidates to resolve segmentation ambiguity. On the seven core datasets of the BOP Benchmark, B2TFPose achieves 40.7 mean AR without refinement and 56.4 with refinement, establishing state-of-the-art performance among training-free RGB methods and outperforming trained counterparts including GigaPose and GenFlow, at competitive inference speed.", "published": "2026-09-06", "comment": "Accepted at BMVC 2026", "url": "https://arxiv.org/abs/2609.06726", "summary": "针对未见物体RGB图像的6DoF位姿估计，提出免训练零样本方法B2TFPose：仅以冻结DINOv2提取稠密patch级特征实现合成到真实泛化，配合测地非极大值抑制检索视角多样模板、渲染引导的Re-Correspondence重建2D-3D对应、多掩码假设选择化解分割歧义。在BOP基准七个核心数据集上无精修达40.7 mean AR、精修后56.4，居免训练RGB方法之首，并超过GigaPose、GenFlow等训练方法。"}, {"id": "2609.06450", "title": "\\textbf{PLATO}: \\emph{Preintegration Learning from Accurate Trajectory Observations} for Neural Inertial Odometry", "authors": ["Haoying Li", "Qihang Liu", "Yifan Peng", "Keyan Miao", "Junfeng Wu"], "abstract": "Neural inertial odometry has demonstrated strong potential for motion estimation in challenging environments, yet inertial-only preintegration remains sensitive to IMU bias and uncertainty. To this end, this paper introduces \\textbf{PLATO}:~\\emph{Preintegration Learning from Accurate Trajectory Observations}, a likelihood-based framework that leverages accurate trajectory observations to jointly learn IMU bias dynamics modeled by a neural ordinary differential equation~(NODE) and gyroscope and accelerometer noise covariances. Optimization exploits the sparse structure of the negative log-likelihood, with IMU noise-parameter gradients computed by forward differentiation. A tailored double-adjoint scheme couples a discrete invariant-error adjoint with a continuous-time adjoint for the bias NODE, enabling memory-efficient likelihood optimization over the nested bias-dynamics and IMU-preintegration rollouts. Validation on EuRoC shows improved performance, and underwater robot experiments demonstrate applicability under intermittent lighting failures and visual degradation.", "published": "2026-09-06", "comment": null, "url": "https://arxiv.org/abs/2609.06450", "summary": "针对神经惯性里程计中惯性预积分对IMU偏置与不确定性敏感的问题，提出基于似然的PLATO框架：利用精确轨迹观测联合学习以NODE建模的IMU偏置动态及陀螺仪、加速度计噪声协方差，并用双伴随方案实现嵌套偏置动态与预积分rollout的内存高效优化。EuRoC验证显示性能提升，水下机器人实验证明其在光照失效与视觉退化下适用。"}, {"id": "2609.07833", "title": "Neural Posterior Estimation for Tomographic Weak Lensing Mass Mapping", "authors": ["Tim White", "Shreyas Chandrashekaran", "Camille Avestruz", "Jeffrey Regier", "the LSST Dark Energy Science Collaboration"], "abstract": "Weak gravitational lensing shear and convergence trace the distribution of baryonic and dark matter across space, making them a powerful probe of cosmic structure. Inferring shear and convergence from images is a challenging inverse problem. The prevailing approach to this task estimates shear from weighted averages of galaxy ellipticities, calibrates these estimates to account for systematic biases, and transforms them to reconstruct convergence, a multistage procedure that requires substantial computational resources and meticulous handling of statistical uncertainties. As an alternative, we propose a probabilistic approach to field-level weak lensing inference in which we train a deep neural network to directly map a multiband image to a variational distribution over the underlying tomographic shear and convergence fields. This neural posterior estimation (NPE) procedure implicitly marginalizes over nuisance variables in the cosmological forward model and does not require evaluating the likelihood function. It is also amortized, so it enables rapid posterior inference for astronomical surveys once the neural network is trained. When evaluated on synthetic images from the LSST-DESC DC2 Simulated Sky Survey, NPE produces well-calibrated variational distributions for shear and convergence that are consistent with the ground truth. We describe how maps sampled from these variational distributions could be used in a subsequent simulation-based inference procedure to approximate the posterior distribution over cosmological parameters.", "published": "2026-09-07", "comment": "17 pages, 10 figures, 1 table", "url": "https://arxiv.org/abs/2609.07833", "summary": "针对弱引力透镜剪切与收敛推断这一计算开销大的困难逆问题，提出神经后验估计（NPE）：训练深度网络把多波段图像直接映射为断层剪切与收敛场的变分分布，边缘化讨厌变量且无需评估似然，训练后可摊销式快速推断。在LSST-DESC DC2合成图像上产生校准且与真值一致的分布，并说明其可支持后续宇宙学参数推断。"}, {"id": "2609.07269", "title": "Singularity-Free Guiding Vector Fields on SO(3) with Designer-Specified Progression Behavior", "authors": ["Jesus Bautista", "Hector Garcia de Marina"], "abstract": "This paper develops a singularity-free guiding vector field (SF-GVF) for path following on the special orthogonal group SO(3). First, we lift the Euclidean SF-GVF construction to SO(3), integrating the augmented-state approach with the intrinsic Lie-group geometry and obtaining a closed-form geometric guidance law whose integral curves converge to a designer-specified attitude path. The field is defined on a dense open subset of SO(3), excluding only the measure-zero antipodal set - a manifestation of the topological obstruction to continuous global stabilization on SO(3). The construction requires no per-step optimization and produces a control input intrinsically in so(3) as body angular rates. Second, we formalize the progression behavior along the path as a designer-supplied function ν(ξ), promoting the parametric speed from an implicitly resolved degree of freedom to a first-class design specification. In contrast to the Euclidean condition v = 0, which excludes vehicles with minimum-speed constraints, the corresponding condition ω= 0 on SO(3) is physically admissible for most platforms with active attitude control, making the progression behavior a design freedom structurally available on SO(3) but absent in the Euclidean setting. The framework's structural results are established under a bi-invariant Riemannian metric and hold uniformly across choices of path, progression, and Lyapunov gain. The framework is illustrated in simulation on self-intersecting paths under both constant and point-convergence progression behaviors.", "published": "2026-09-07", "comment": "12 pages, submitted to Automatica", "url": "https://arxiv.org/abs/2609.07269", "summary": "面向SO(3)上的路径跟踪，将欧氏无奇点引导矢量场构造提升到该李群，结合增广状态法与内蕴几何得到闭式制导律，其积分曲线收敛到指定姿态路径，场仅排除测度零的对径集；并把沿路径推进行为形式化为设计者指定函数。结构性结果在双不变黎曼度量下一致成立，并以自交路径仿真演示。"}, {"id": "2609.07049", "title": "Large Discrete Policy: Advancing Explicit Behavior Modeling with Stochastic Iterative Scoring", "authors": ["Zhenxin Li", "Nadine Chang", "Xinglong Sun", "Jingde Chen", "Wenhao Yao", "Zi Wang", "Maying Shen", "Yu-Gang Jiang", "Zuxuan Wu", "Shiyi Lan", "Jose M. Alvarez"], "abstract": "Behavior policies are often formulated as continuous generative models, whose iterative denoising processes are expressive but difficult to interpret and prone to producing implausible actions. We propose the Large Discrete Policy (LDiP), a fully discrete behavior modeling framework that selects actions from a large vocabulary of physically plausible candidates. Rather than perturbing actions, LDiP improves expressivity through stochastic iterative scoring: it progressively re-scores and prunes candidates with score-space stochasticity, enabling fine-grained ranking and exploration among plausible actions while preserving an explicit decision process. Across end-to-end planning, closed-loop driving, robotic manipulation, and vision-language-action settings, LDiP consistently outperforms strong discrete and continuous baselines in autonomous driving, and exceeds or matches continuous generative policies in robotic manipulation. These results show that discrete policies, when equipped with effective scoring mechanisms, offer an expressive, plausible, and interpretable alternative for behavior modeling. Project website: https://zhenxinli.net/LargeDiscretePolicy/.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07049", "summary": "针对生成式行为策略难解释且易产生不合理动作的问题，提出全离散行为框架LDiP：从物理合理的候选动作词表中选动作，以随机迭代评分重评分并剪枝候选，保留显式决策过程，实现细粒度排序与探索。其在自动驾驶上一致优于强离散与连续基线，机器人操作上超过或匹配连续生成策略。"}]}, "rep": {"name": "三维表示与重建", "papers": [{"id": "2609.06874", "title": "MedGSSR: Generalizable Medical Image Super-Resolution 3D Reconstruction via Hierarchical Feed-forward Gaussian Splatting", "authors": ["Chengkai Wang", "Luoyu Hong", "Yiting Zhao", "Jiamin Wang", "Xiang Feng", "Feiwei Qin", "Zhenzhong Kuang", "Xuefei Yin", "Ali Bashashati", "Yanming Zhu"], "abstract": "High-resolution volumetric medical imaging is critical for clinical diagnosis, yet acquisition is often limited by scanner hardware, scan time, and for CT, radiation dose. Medical 3D Super-Resolution (Med3DSR) offers a computational alternative, but existing methods commonly rely on per-subject optimization, pretrained priors, or coordinate-based implicit representations, which compromise anatomical fidelity and limit efficiency. To address these limitations, we present MedGSSR, a fully end-to-end feed-forward framework that represents volumes as an explicit 3D Gaussian field for Med3DSR. Unlike coordinate-based implicit functions, our explicit 3D Gaussian representation naturally enhances signal continuity and local high-frequency fidelity. Specifically, MedGSSR explicitly decouples the reconstruction process into coarse-grained structural preservation and fine-grained textural refinement through the proposed Pyramid Anatomical Encoder and a Hierarchical Gaussian Projector. To support arbitrary-scale super-resolution, we introduce sub-voxel Gaussian decomposition and a Differentiable Gaussian Voxelizer that directly queries the continuous 3D intensity field, reducing discretization artifacts. Extensive experiments on MRI and CT benchmarks demonstrate that MedGSSR significantly outperforms state-of-the-art methods. Notably, our framework exhibits robust generalizability across unseen datasets without requiring per-subject optimization, enabling fast inference and high-fidelity volumetric super-resolution in practical clinical settings. Our project webpage, including code, is at https://william2ai.github.io/medgssr", "published": "2026-09-06", "comment": "ECCV 2026", "url": "https://arxiv.org/abs/2609.06874", "summary": "针对医学3D超分现有方法依赖逐对象优化、预训练先验或隐式坐标表示而损害保真与效率的问题，提出全端到端前馈框架MedGSSR：以显式3D高斯场表示体数据，经金字塔解剖编码器与分层投影器解耦结构与纹理细化，并以可微体素器支持任意尺度。MRI与CT基准上显著优于SOTA，跨未见数据集无需逐对象优化即泛化且推理快。"}, {"id": "2609.07734", "title": "TV-SGS: Gaussian Splatting with Geometric Information Propagation via Tensor Voting under sparse views", "authors": ["Harish N Sathishchandra", "Philippos Mordohai"], "abstract": "Gaussian Splatting has been effective in inferring scene representations that excel in novel view synthesis. Multiple splats cooperate seamlessly to synthesize the pixels of novel views and are jointly optimized even though they only affect each other indirectly, via pixels they project to in common. We present an approach that enables direct communication among splats to enhance the geometric structures they form in 3D. This is accomplished by Tensor Voting, which was originally designed to infer structures from noisy inputs and has been adapted here to provide supervision during test-time optimization, leading to more accurate scene geometry. We introduce a new class of 3D losses that do not rely on rendering and can be combined with essentially all losses previously reported in the literature. Our 3D losses are especially effective when the input views are sparse and geometric regularization is essential due to limited supervision from the images. Our method is easy to integrate with a diverse set of backbones, and our experiments on the DTU and Tanks-and-Temples datasets demonstrate that TV-SGS improves the geometry of the outputs compared to the backbone, while maintaining or improving rendering quality.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07734", "summary": "针对稀疏视图下Gaussian Splatting几何监督不足的问题，提出TV-SGS：将Tensor Voting改造为测试时优化中的监督信号，使高斯椭球间直接通信以增强其构成的3D几何结构，并提出一类不依赖渲染的3D损失，可与已有损失广泛组合、易于集成到多种骨干。DTU与Tanks-and-Temples实验显示其相较骨干改善了输出几何，同时保持或提升渲染质量。"}, {"id": "2609.07346", "title": "From Explicit References to Scene Manifolds: Distributional Fidelity and Realism for Radiance Field Quality Assessment", "authors": ["Saeed Mahmoudpour", "Gi-Mun Um", "Hyon-Gon Choo", "Peter Schelkens"], "abstract": "Radiance field representations such as 3D Gaussian Splatting (3DGS) enable high-quality novel view synthesis but can introduce complex, view-dependent artifacts from reconstruction, rendering, and compression. Reliable perceptual quality assessment (QA) is thus essential for evaluating rendered views and guiding the design of perceptually faithful scene representations. Existing full-reference QA metrics require an aligned reference image, while recent cross-reference metrics relax this requirement by comparing a test view with non-aligned references. However, under wide-baseline radiance field settings, selecting a reliable nearby reference can be difficult, particularly when evaluating views along arbitrary trajectories and poses. We propose SCODA, a lightweight scene-conditioned objective QA method that shifts QA from explicit image-to-image comparison to scene-manifold modeling. High-quality observations of each scene are represented as a multivariate Gaussian distribution in deep feature space, producing a semantic fidelity score that measures deviation from the scene distribution. A weakly-supervised distortion-aware patch discriminator provides a complementary realism signal, and both cues are combined through an unsupervised bounded fusion strategy. Experiments on multiple benchmarks show strong agreement with human judgments and robust generalization across GS- and NeRF-generated views and trajectories. Code is publicly available at https://gitlab.com/saeedmp/scoda.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07346", "summary": "针对辐射场质量评估中全参考需对齐参考图、交叉参考在宽基线下难选参照，提出轻量场景条件方法SCODA：把每场景高质量观测建模为深层特征空间的多元高斯分布，以偏离度量语义保真，并用弱监督判别器提供真实感信号，经无监督融合结合。多基准上与人类判断高度一致，跨GS与NeRF视图稳健泛化。"}, {"id": "2609.08730", "title": "CVT-GS: Learning to Simplify 3D Gaussian Splatting with Centroidal Voronoi Tessellation", "authors": ["Bingxian Li", "Yilong Li", "Jingliang Peng", "Peng-Shuai Wang", "Fei Zhu", "Guozheng Li", "Chi Harold Liu", "Guoping Wang", "Bo Pang"], "abstract": "While 3D Gaussian Splatting (3DGS) has emerged as a powerful representation for real-time novel view synthesis, rendering high-fidelity scenes often relies on a massive number of Gaussian primitives, incurring substantial storage and computational overhead. Existing simplification techniques are largely intrusive, requiring training-time pruning, architectural modifications, or computationally expensive per-scene fine-tuning. These drawbacks limit their deployment on off-the-shelf pretrained models. In this paper, we propose CVT-GS, a novel optimization-free post-hoc simplification framework that directly compresses trained 3DGS scenes without sacrificing visual fidelity. Our approach first constructs spatially coherent cells over Gaussian centers via a geometry-aware Centroidal Voronoi Tessellation (CVT). Subsequently, a lightweight neural cell merger predicts the geometry and appearance of a single, highly representative Gaussian primitive for each cell under differentiable rendering supervision. By formulating simplification as a rendering-aware many-to-one merging process rather than naive primitive pruning, CVT-GS outputs a standard 3DGS scene that is seamlessly compatible with existing renderers. Experiments on various datasets demonstrate the superiority of our method. Notably, when achieving a 100-fold reduction in Gaussian points, our method operates 12 times faster than state-of-the-art methods while improving the PSNR by 1.3 dB.", "published": "2026-09-08", "comment": null, "url": "https://arxiv.org/abs/2609.08730", "summary": "针对3DGS高保真渲染依赖海量高斯基元、现有简化方法侵入式且需逐场景微调的问题，提出免优化的事后简化框架CVT-GS：用几何感知质心Voronoi剖分在高斯中心上构建空间一致单元格，由轻量神经合并器在可微渲染监督下为每格预测单个代表性高斯，输出兼容现有渲染器的标准3DGS场景。高斯点缩减100倍时其比SOTA快12倍且PSNR提高1.3 dB。"}, {"id": "2609.07231", "title": "Generalizable 6D Pose Estimation of Textureless Objects with Planar-based Gaussian Splatting", "authors": ["Jie Lu", "Hengtan Zhang", "Li Gong", "Pengpeng Wang", "Xianjia Yu", "Jinxiang Deng", "Tomi Westerlund", "Zhongxue Gan", "Lirong Zheng", "Zhuo Zou"], "abstract": "Estimating the 6D pose of textureless objects without prior CAD models remains a critical challenge due to the lack of appearance features. While recent generalizable approaches alleviate the dependence on object-specific models, their performance on low-texture objects is often limited by insufficient geometric constraints in the underlying representations. In this work, we propose PG-Pose, a geometry-aware framework combining Planar-based Gaussian Splatting (PGS) reconstruction and Geometry-driven pose optimization. In the offline representation extraction stage, three distinct representations of the object are extracted from multi-view reference RGB images with known poses. PG-Pose reconstructs a 3D Gaussian representation and renders high-fidelity depth maps to generate 3D point clouds through back projection. In the online pose inference stage, the initial pose of the input image is estimated by 2D-3D correspondence matching between the input image and the reconstructed 3D point clouds, followed by a PGS-Refiner for iterative pose optimization. Evaluations on the OnePose-LowTexture datasets, PG-Pose achieves an average accuracy of 94.2% ADD(S)@0.1d, with a 2.1% improvement average accuracy compared with the state-of-the-art (SOTA) GS-based approach. To further demonstrate the effectiveness of PG-Pose for industrial robots in grasping tasks, we deploy it on a dual-arm industrial robot and successfully realize the grasping task on an unseen object.", "published": "2026-09-07", "comment": "7 pages, 5 figures. Accepted by the IEEE/RSJ International Conference on Intelligent Robots and Systems (IROS 2026)", "url": "https://arxiv.org/abs/2609.07231", "summary": "针对无CAD模型的无纹理物体6D位姿估计中现有泛化方法几何约束不足的问题，提出PG-Pose：离线从已知位姿的多视角参考图像以平面基高斯溅射重建3D表示并渲染高保真深度图生成点云，在线由2D-3D对应匹配得初始位姿，再经PGS-Refiner迭代优化。OnePose-LowTexture上平均精度94.2% ADD(S)@0.1d，较SOTA GS方法提高2.1%，并部署于双臂机器人完成未见物体抓取。"}, {"id": "2609.08332", "title": "EdMCGS: Event-Driven Markov Chain Gaussian Splatting for Extreme-Low-Frame-Rate Dynamic Scene Reconstruction", "authors": ["Yuzhong Wang", "Wenmin Wang", "Xinxing Yu"], "abstract": "We present EdMCGS (Event-driven Markov chain Gaussian Splatting), an end-to-end method for reconstructing dynamic 3D scenes from extreme-low-frame-rate RGB together with an event stream, which can then be rendered at any intermediate timestamp. Methods relying solely on RGB images generate numerous artifacts due to the lack of evidence from between consecutive frames. To supply this missing evidence, we model the scene motion as an event-driven Markov chain, in which the sparse RGB frames anchor the state at their own timestamps while the events recorded within an interval drive the transition across it. Since the transition reads the events of the current interval, it remains active at inference and produces the in-between motion of the 3D Gaussians directly from the events rather than by interpolation, which sets our method apart from prior work that uses events only as training-time supervision. The state is carried by a compact set of control points, each driven by the events sampled in the neighborhood of its own image projection, and a temporal local isometry term keeps the propagated motion locally rigid. Experiments on synthetic and real-world scenes show that EdMCGS outperforms both RGB-based and event-based baselines, while rendering in real time with far fewer Gaussians than the strongest event-based baseline. We release our source code and a new dataset at https://github.com/joseclipse/EdMCGS.", "published": "2026-09-08", "comment": "29 pages, 3 figures", "url": "https://arxiv.org/abs/2609.08332", "summary": "针对极低帧率RGB下动态场景重建缺乏帧间证据的问题，提出端到端方法EdMCGS：将场景运动建模为事件驱动的马尔可夫链，稀疏RGB帧锚定状态、区间内事件驱动转移，推理时由事件直接生成3D高斯的帧间运动而非插值，并以控制点承载状态。合成与真实场景上优于RGB和事件基线，实时渲染且高斯数远少于最强事件基线。"}, {"id": "2609.07724", "title": "Zero-Shot 3D Plant Organ Segmentation with SAM3 and Semantic NeRFs", "authors": ["Andreas Gilson", "Laura Hennig", "Peter Pietrzyk"], "abstract": "Accurate 3D plant organ segmentation is fundamental to automated phenotyping. Existing approaches rely on annotated training data or species-specific model configurations. We present an annotation-free pipeline for 3D plant organ segmentation, combining text-prompted SAM3 segmentation with semantic neural radiance fields (NeRFs). Given only multi-view RGB images and a list of class names, our zero-shot pipeline produces semantically labeled 3D point clouds without manual annotation, per-species fine-tuning, or domain-specific preprocessing. Multi-view NeRF fusion acts as effective implicit consensus mechanism that lifts imperfect per-frame masks into accurate 3D labels. On a controlled Begonia maculata testbed the SAM3 pipeline achieves 92.6% mIoU, reaching 95.9% of the oracle upper bound established with perfect ground-truth masks. The pipeline was further evaluated on a new dataset spanning ten diverse plant point clouds reaching an average 0.856 mIoU, with leaf and pot IoU above 0.91 and 0.90 for every species, respectively. These results demonstrate that annotation-free 3D plant organ segmentation is now feasible and approaching the range of supervised methods.", "published": "2026-09-07", "comment": "Submitted to CVPPA Workshop at ECCV 2026", "url": "https://arxiv.org/abs/2609.07724", "summary": "针对3D植物器官分割依赖人工标注或物种特定配置的问题，提出免标注零样本流水线：结合文本提示的SAM3分割与语义NeRF，仅需多视角RGB图像与类别名列表，由多视角NeRF融合充当隐式共识机制，把不完美逐帧掩码提升为准确3D标签。秋海棠测试床上达92.6% mIoU（为oracle上限的95.9%）；十种植物新数据集上平均mIoU 0.856，叶片与花盆IoU分别高于0.91和0.90。"}, {"id": "2609.07557", "title": "Heat Kernel Textures: the Geodesic Gaussians That Do Not Splat", "authors": ["Simone Foti", "Caner Korkmaz", "Stefanos Zafeiriou", "Tolga Birdal"], "abstract": "3D Gaussian Splatting has recently revolutionised novel view synthesis as well as many other 3D vision methods and applications. Drawing inspiration from this representation, we now rethink textures to overcome the main issues of UV mapping while considerably lowering their memory footprint. Heat Kernel Textures (HKTex) eliminate UV unwrapping as well as their persistent issues of wasted UV space, seams, distortions, vertex-duplication, and varying resolution. Grounded in discrete Riemannian geometry and intrinsically defined on any manifold surface discretised as a triangular mesh, HKTex uses anisotropic heat kernels as geodesic equivalents to Gaussians. Like our kernels, also the optimisation of their position and the adaptive densification strategies were redefined to operate on the surface of the object to be textureised. Our novel representation is also fully integrated with a physically based renderer and can be optimised either from existing textures or multi-view images. Our project page and code are available at circle-group.github.io/research/HeatKernelTextures.", "published": "2026-09-07", "comment": "ECCV 2026 (Long Oral)", "url": "https://arxiv.org/abs/2609.07557", "summary": "针对UV纹理映射的空间浪费、接缝、畸变、顶点复制与分辨率不一等问题，提出Heat Kernel Textures：基于离散黎曼几何，以各向异性热核作为高斯的测地等价物，内在定义于任意三角网格表面，免UV展开并显著降低内存占用；其位置优化与稠密化均在物体表面进行，并与物理渲染器集成，可由已有纹理或多视角图像优化。"}, {"id": "2609.06723", "title": "ADELE - Adaptive Delaunay Grids for High-Fidelity Mesh-Native Reconstruction", "authors": ["Johannes Weidenfeller", "Shaofei Wang", "Philipp Fürnstahl", "Siyu Tang"], "abstract": "Meshes remain the most practical representation for geometry reasoning and integration into graphics pipelines, yet existing reconstruction methods struggle to produce high-quality meshes. Most state-of-the-art approaches initially learn an intermediate representation (NeRF/3DGS) and treat mesh extraction as a post-processing step, which often leads to oversmoothed surfaces or poor quality meshes with excessive triangle counts.Existing mesh-native optimization methods alleviate some of these issues but suffer from fixed-resolution discretizations and unstable optimization behavior. In this paper, we introduce an adaptive mesh-based optimization framework and a practical mesh rendering technique to address these challenges. Our representation combines an optimizable Delaunay-triangulated tetrahedral grid with a multi-resolution hash grid. The former is refined through point pruning and insertion, while the latter provides latent features for SDF/appearance value predictions. We use volumetric rendering to bootstrap a coarse geometry while leveraging mesh-based rendering for recovering fine-grained details. Additionally, we propose a differentiable, rasterization-based depth-offset rendering formulation, reducing geometric artifacts and improving reconstruction quality. Our method significantly outperforms existing mesh optimization approaches across a variety of object-centric benchmarks while being competitive with state-of-the-art NeRF/3DGS methods.", "published": "2026-09-06", "comment": "Accepted to SIGGRAPH Asia 2026 Conference Papers | Project page: https://johannes-weidenfeller.github.io/adele | Code: https://github.com/johannes-weidenfeller/adele", "url": "https://arxiv.org/abs/2609.06723", "summary": "针对先学中间表示再提网格导致过平滑或三角形过多、网格原生优化受固定分辨率与不稳定优化之困的问题，提出自适应网格优化框架ADELE：结合可优化Delaunay四面体网格与哈希网格，以体渲染引导粗几何、网格渲染恢复细节，并以可微深度偏移渲染减少伪影。多个物体基准上显著超过现有网格优化方法，与SOTA NeRF/3DGS相当。"}, {"id": "2609.07145", "title": "EquiGQNet: Fast Grasp Quality Evaluation via Shared Equivariant Point Cloud Encoding", "authors": ["Sungwon Seo", "Jaeseog Won", "Jiyou Shin", "Youngjin Seo", "Hyunjun Kim", "Seokmin Yoon", "Tuan Luong", "Hyungpil Moon"], "abstract": "Planning six-degree-of-freedom (6-DoF) grasps for unseen objects in cluttered tabletop scenes from a single-view depth image requires accurate and efficient evaluation of diverse grasp candidates. Existing early-fusion methods capture local object geometry relative to each grasp candidate but repeatedly encode the scene, whereas late-fusion methods reuse a shared scene representation but may lose this grasp-relative local geometry. We propose EquiGQNet, an efficient 6-DoF grasp quality evaluator that combines the strengths of both approaches. For grasp orientation, EquiGQNet replaces the early-fusion operation of rotating and re-encoding the point cloud for each grasp candidate with an SO(3)-equivariant encode-once-then-rotate scheme, yielding grasp-aligned geometric features from a shared scene encoding. For grasp translation, Mid-level Action Fusion (MAF) injects the grasp position into intermediate features before global aggregation, retaining local geometry relative to each candidate. We evaluate EquiGQNet in two grasp planning pipelines: Cross-Entropy Method (CEM)-based continuous grasp search and candidate ranking with a pretrained generative planner. In simulation, EquiGQNet achieves grasping performance comparable to the early-fusion baseline and substantially outperforms late fusion on objects with complex geometry and limited graspable regions, while reducing CEM planning time from 3.31s to 0.48s, a 6.9x speedup over early fusion. In real-world household-object decluttering, EquiGQNet achieves a 95.2% grasp success rate and 230 picks per hour, versus 153 and 170 for early- and late-fusion baselines. Code is available at https://equigqnet.github.io/.", "published": "2026-09-07", "comment": "8 pages, 6 figures, 4 tables. Submitted to IEEE Robotics and Automation Letters (RA-L)", "url": "https://arxiv.org/abs/2609.07145", "summary": "针对杂乱场景未见物体6-DoF抓取评估中早融合反复编码场景、晚融合丢失抓取相对局部几何的问题，提出EquiGQNet：以SO(3)等变的编码一次再旋转方案从共享编码得到抓取对齐特征，并以Mid-level Action Fusion在聚合前注入抓取位置保留局部几何。仿真中接近早融合基线、明显优于晚融合，CEM规划时间由3.31s降至0.48s；真实整理任务抓取成功率95.2%、每小时230次。"}, {"id": "2609.07738", "title": "TFTrack: A Template-Free Framework for Efficient 3D Point Cloud Tracking", "authors": ["Zhaofeng Hu", "Sifan Zhou", "Jiahao Nie", "Ziyu Zhao", "Weizi Li", "Ci-jyun Liang"], "abstract": "LiDAR-based 3D Single Object Tracking (3D SOT) is critical for robotic perception and navigation and aims to localize dynamic objects across frames in sparse point clouds. Existing methods, rooted in the Siamese tracking paradigm from 2D vision, rely on costly dual-input designs and excessive motion modeling guided by template priors, hindering their efficiency. Our in-depth analysis reveals: (i) the template paradigm is redundant, as the previous bounding box center encodes sufficient historical context; (ii) complex motion modeling is unnecessary, as geometric alignment provides adequate motion priors. Based on the above findings, we propose the first Template-Free Tracking framework (TFTrack). The novel framework eliminates the need for template-search pairings and operates directly on the current frame guided solely by the prior bounding box center and size. We instantiate this paradigm into three variants: TFTrack-Voxel, TFTrack-Pillar, and TFTrack-Point, to explore different 3D representations under a unified framework, ensuring flexibility across sparse and dense scenes. Extensive experiments on KITTI and nuScenes benchmarks show that TFTrack is competitive with leading template-based trackers, while reducing FLOPs by approximately 50% and running at approximately 120 FPS. By simplifying overcomplicated motion-centric designs, TFTrack establishes a new minimalist paradigm for efficient 3D point cloud tracking, paving the way for real-time and resource-efficient deployment in embedded robotic systems, such as autonomous vehicles. The code is available at https://github.com/tftrack-anonymous/TFTrack/tree/main.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07738", "summary": "针对LiDAR 3D单目标跟踪中Siamese范式依赖模板与复杂运动建模而效率受限的问题，分析表明模板冗余（上一帧包围盒中心已含足够历史信息）且几何对齐即可提供运动先验，据此提出首个免模板框架TFTrack：仅凭先验包围盒中心与尺寸在当前帧直接跟踪，提供Voxel、Pillar、Point三种变体。KITTI与nuScenes上与领先模板法具竞争力，FLOPs约减50%、约120 FPS。"}, {"id": "2609.06959", "title": "MSSP: Multi-Scale Spatially-Constrained Partition for Unsupervised Semantic Segmentation of 3D Point Clouds", "authors": ["Zhenghao Zhang", "Xinjie Wang", "Wei Wang", "Jun Zhang", "Hanyun Wang"], "abstract": "3D point cloud semantic segmentation is essential for real-world spatial understanding, yet the prohibitive cost of human annotations motivates unsupervised approaches that require no labels. Existing superpoint-based methods typically rely on spectral analysis at a fixed granularity, failing to capture the hierarchical semantic structures inherent in complex indoor scenes. To bridge this gap, we present a Multi-Scale Spatially-Constrained Partition (MSSP) framework that combines multi-scale spectral analysis with spatially-constrained clustering. Multi-scale spectral analysis constructs enriched superpoint descriptors across multiple clustering granularities; however, the resulting high-dimensional feature space calls for a structural prior to translate into cleaner segmentation. Spatially-constrained clustering supplies this prior by restricting superpoint merging to physically adjacent regions, imposing the spatial coherence needed for multi-scale features to be effective. Extensive experiments on S3DIS and ScanNet show that MSSP achieves the best mIoU among unsupervised methods on the main benchmarks, with particularly significant gains on S3DIS. Notably, our ablation reveals a regularize-then-enrich interaction: multi-scale features alone do not improve final segmentation, yet become highly effective when coupled with spatial regularization, underscoring that spatial coherence is aprerequisite for multi-scale representations in superpoint clustering.", "published": "2026-09-07", "comment": "Accepted by the International Conference on Image and Graphics (ICIG 2025), Springer LNCS", "url": "https://arxiv.org/abs/2609.06959", "summary": "针对无监督3D点云分割中superpoint方法固定粒度谱分析难以捕捉层次语义结构的问题，提出MSSP框架：多尺度谱分析在多个聚类粒度上构建增强superpoint描述子，空间约束聚类限制superpoint只与物理相邻区域合并，提供所需空间一致性先验。S3DIS与ScanNet上取得无监督方法最佳mIoU、S3DIS增益尤显著；消融显示多尺度特征须与空间正则耦合才有效。"}]}, "ff": {"name": "前馈几何（VGGT 一系）", "papers": [{"id": "2609.07414", "title": "RelightFormer: Feed-forward Generative Transformer for Multiview Object Relighting", "authors": ["Hejun Wang", "Jinxi Li", "Junwei Jiang", "Shiwei Mao", "Hu Cheng", "Shouwang Huang", "Bo Yang"], "abstract": "Image relighting is traditionally tackled via complex inverse rendering pipelines, which suffer from ill-posed optimization, or single-image generative models that ignore crucial multi-view cues necessary for understanding 3D geometry and material interactions. To address these limitations, we introduce a feed-forward generative Transformer for direct single- and multi-view image relighting that entirely bypasses explicit intrinsic property estimation. Adapted from a video foundation model, our architecture features a latent illumination module that dynamically injects target environment maps into spatial features via cross-attention. Furthermore, we employ permutation-invariant positional encodings to symmetrically process unordered multi-view inputs without sequential bias. To train this robust data-driven model, we construct the massive Laval Objaverse Dataset (LOD), comprising 90K objects and 39K unique illuminations. Extensive experiments demonstrate state-of-the-art visual quality, photorealistic relighting quality, and strong zero-shot generalization across single-view, multi-view, and novel-view relighting tasks.", "published": "2026-09-07", "comment": "SIGGRAPH Asia 2026. Hejun and Jinxi are co-first authors. Code and data are available at: https://github.com/vLAR-group/RelightFormer", "url": "https://arxiv.org/abs/2609.07414", "summary": "针对逆渲染重光照病态、单图生成方法忽略多视角线索的问题，提出前馈生成Transformer RelightFormer，直接完成单/多视图重光照、无需显式内参估计：潜空间光照模块以交叉注意力注入环境贴图，以置换不变位置编码处理无序多视图输入，并以含9万物体、3.9万光照的LOD数据集训练。实验显示其取得SOTA重光照质量，零样本泛化强。"}, {"id": "2609.07525", "title": "When Semantically Consistent Encoding Meets View-Label Heterogeneity Modeling: A Unified Framework for Incomplete Multi-View Multi-Label Learning", "authors": ["Chengliang Liu", "Bo Li", "Bob Zhang", "Yanghao Zhou", "Jie Wen", "Wenwu Wang"], "abstract": "Incomplete multi-view multi-label learning requires not only robust semantic aggregation from partially observed views, but also label-aware exploitation of view-specific evidence. Existing approaches usually emphasize either shared representation learning or decision-level fusion. The former improves robustness against missing views, yet tends to compress label-discriminative view-specific cues into a single latent representation. The latter preserves individual view predictions, but often relies on fixed or globally learned fusion weights, ignoring that different labels of different instances may require different views. To address these limitations, this paper presents V2L, a unified representation-decision framework for incomplete multi-view multi-label classification. On the representation side, V2L constructs semantically consistent variational posteriors from incomplete views through a perturbation-aware encoding mechanism, which provides a stable shared semantic basis. On the decision side, V2L introduces an active view-label relevance modeling strategy that estimates instance-wise and label-wise view contributions, allowing each label prediction to adaptively select useful view-specific evidence. From the perspective of model architecture, these two important strategies are integrated into a unified framework through a hybrid fusion architecture, simultaneously meeting the requirements of cross-view semantic consistency and representational complementarity. Extensive experiments under both incomplete and complete settings show that V2L achieves leading performance on five benchmarks. Code is available at: https://github.com/justsmart/V2L.", "published": "2026-09-07", "comment": "Accepted by IEEE TPAMI", "url": "https://arxiv.org/abs/2609.07525", "summary": "针对不完整多视图多标签学习中共享表示压缩视图特定判别线索、决策融合权重固定而忽略实例与标签差异的问题，提出统一框架V2L：以扰动感知编码构建语义一致的变分后验，并以视图-标签相关性建模估计实例级与标签级视图贡献，让每个标签预测自适应选取视图证据，五个基准上均取得领先性能。"}, {"id": "2609.07415", "title": "Self-Supervised Multi-View 3D Gaze Target Estimation via Probabilistic Ray Marching", "authors": ["Keqi Chen", "Vinkle Srivastav", "Nicolas Padoy"], "abstract": "We present a self-supervised approach, Self-MVGTE, for estimating 3D gaze targets from multiple camera views. Unlike existing methods that independently estimate 2D gaze targets per camera view, Self-MVGTE predicts gaze targets directly in 3D space for the first time. Moreover, it does not require any ground-truth annotations from the target scene and uses only the multi-view input images from a calibrated camera setup, pseudo 2D gaze target labels from a monocular gaze target estimation model, and 3D gaze vectors from a monocular 3D gaze estimation model. A key challenge is that these pseudo labels are inherently noisy and multi-view inconsistent. To address this, we propose a probabilistic ray marching framework, which models the uncertainty of these pseudo labels and exploits 3D gaze vectors as geometric priors. Specifically, these gaze vectors are first integrated into the monocular gaze target estimation model to improve its generalization to unseen scenes, producing higher-quality pseudo labels. Then, for 3D gaze target estimation, we construct a 3D gaze cone by casting a bundle of rays from the eye position around the gaze vector to strictly constrain the solution space. Within this cone, we propose a depth-guided feature sampling strategy using off-the-shelf DINOv2 and Depth-Anything-3 models, and estimate a spatial likelihood distribution of the gaze target. Finally, we convert the pseudo gaze target labels into a target distribution and softly optimize the network. Extensive experiments on the MVGT dataset show that Self-MVGTE achieves state-of-the-art performance, surpassing existing fully-supervised baselines.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07415", "summary": "针对多视角3D注视目标估计缺乏真值标注，提出自监督方法Self-MVGTE：仅用标定多视角图像、单目伪2D标签与3D注视向量，以概率光线行进建模伪标签不确定性——先融入注视向量提升单目伪标签质量，再由眼位置投射线束构成注视锥约束解空间，锥内做深度引导采样估计目标似然分布。MVGT数据集上达SOTA，超过全监督基线。"}, {"id": "2609.07258", "title": "MV-STRIDE: Enabling MLLMs to Master Multi-View Spatial Reasoning via Hierarchical Capability Modeling", "authors": ["Jin Xu", "Xiaojian Huang", "Zhuodong Luo", "Zhihong Zhang", "Xin Liu", "Jiansheng Wei", "Xinzhi Wang", "Jie Zhao", "Xuejin Chen"], "abstract": "Despite the rapid progress of Multimodal Large Language Models (MLLMs) in 2D vision-language tasks, robust multi-view spatial reasoning remains a fundamental bottleneck due to the lack of structured 3D cognitive pathways in existing datasets. To address this, we introduce MV-STRIDE, a Multi-View hierarchical SpaTial Reasoning dataset with Interdependent and DEcomposed capabilitiEs. Moving beyond flat data structures, MV-STRIDE explicitly models the dependency relationships between foundational perception, scene understanding, and complex contextual reasoning, providing a coherent learning pathway aligned with human spatial cognition. We develop a systematic QA generation pipeline leveraging diverse 3D scene sources that enforces cross-view dependency constraints to prevent single-view solvability, generating multi-level spatial reasoning tasks supported by cognitively grounded chain-of-thought supervision for complex inference. Extensive evaluations demonstrate that our multi-stage training framework based on our hierarchical dataset achieves state-of-the-art performance across multiple spatial reasoning benchmarks, notably the multi-view oriented MMSI-Bench. Our approach enables MLLMs to maintain robust, 3D-consistent spatial reasoning across diverse viewpoints. The code and dataset are available at https://co1dspring.github.io/MV-STRIDE/.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07258", "summary": "针对多模态大模型多视图空间推理薄弱的问题，构建分层空间推理数据集MV-STRIDE：显式建模基础感知、场景理解与复杂推理间的依赖关系，QA生成流程施加跨视图依赖约束以防止单视图可解，并以认知依据的思维链监督支撑多阶段训练。评测显示其在多个空间推理基准上达SOTA，尤以多视图的MMSI-Bench为甚。"}, {"id": "2609.08848", "title": "FIRE3D: Feed-forward Interactive 3D Scene Reconstruction Within A Minute", "authors": ["Hongchi Xia", "Tianhang Cheng", "Wei-Chiu Ma", "Shenlong Wang"], "abstract": "We present FIRE3D, a unified framework that takes a single RGB image or casual RGB video and transforms it into simulation-ready 3D scene assets for games and interactive applications in under a minute. At the core of FIRE3D is a feed-forward, end-to-end network that predicts a compositional scene representation from posed RGB-D observations estimated from the RGB capture, including the 6-DoF pose, bounding box, mesh, and texture for every object. By modeling the scene as a collection of discrete entities, FIRE3D produces amodally complete and simulation-ready environments where objects are physically decoupled and ready for interaction. Our framework requires no test-time optimization, runs orders of magnitude faster than prior interaction-ready methods, and provides object-level completeness beyond existing feed-forward 3D approaches. We demonstrate competitive or state-of-the-art results across pose accuracy, geometry completeness, and texture quality across various datasets while being orders of magnitudes faster. Project page: https://xiahongchi.github.io/Fire3D/", "published": "2026-09-08", "comment": "Project page: https://xiahongchi.github.io/Fire3D/", "url": "https://arxiv.org/abs/2609.08848", "summary": "针对从单张RGB图像或随手拍视频生成游戏等交互应用的仿真就绪3D资产，提出统一前馈框架FIRE3D：从RGB估计的RGB-D观测预测组合式场景表示，输出各物体的6-DoF位姿、包围盒、网格与纹理，场景建模为物理解耦的可交互实体集合，无需测试时优化。在位姿、几何与纹理上具竞争力或达SOTA，且比已有可交互方法快数个数量级。"}, {"id": "2609.08345", "title": "CoVeR: Coverage-Based Token Pruning for Multi-View 3D Reasoning in VLMs", "authors": ["Nhat-Tan Bui", "Varshini Elangovan", "Arun Reddy Anugu", "Sreyas Mohan", "Wei Ye", "Dilin Wang", "JQ Huang", "Rakesh Ranjan", "Aviral Chharia", "Fernando De la Torre"], "abstract": "Representing a 3D scene as multi-view images allows 2D VLMs to reason in 3D by reusing priors from pre-training, sidestepping the scarcity of annotated 3D data. However, it produces thousands of redundant visual tokens whose cost grows with every view. Existing visual token pruners fall into two families, each limited in the 3D multi-view setting. Learned importance methods rank tokens by attention or encoder features; because redundancy here is fundamentally spatial, they keep near-duplicate tokens from a few prominent regions and leave most of the scene unrepresented. Voxelization methods improve spatial coverage but cannot enforce an exact token budget and saturate as multi-view observations overlap in 3D, capping retention well below the target. We show that spatial coverage is associated with 3D reasoning performance and introduce CoVeR, a deterministic, training-free selector that uses only token coordinates, with no learned signals. CoVeR selects tokens that collectively cover every region of the scene, and solves the limitations of both families: it enforces an exact per-scene budget, breaks the voxelization saturation plateau, and avoids the near-duplicate selections of learned importance. Extensive experiments show CoVeR outperforms prior SOTAs on all three 3D reasoning benchmarks and generalizes as a plug-and-play module tested across four VLMs. Notably, with only $\\approx$8% of visual tokens, it preserves 93.5% of full-token performance, surpassing SOTA by 3.9 percentage points on average across benchmarks.", "published": "2026-09-08", "comment": "21 pages, 17 figures", "url": "https://arxiv.org/abs/2609.08345", "summary": "针对多视图3D推理中视觉token随视图增长、现有剪枝器或保留近重复token或无法精确控制预算的问题，提出确定性免训练选择器CoVeR：仅用token坐标，选出能共同覆盖场景每个区域的token，从而强制精确的逐场景预算并突破体素化方法的饱和上限。其在三个3D推理基准上超过SOTA，可即插即用于四种VLM，仅用约8%的token即保留93.5%的性能。"}]}, "wm": {"name": "世界模型", "papers": [{"id": "2609.09123", "title": "Mask Forcing: Improving Autoregressive Video Diffusion Distillation via Dual-Noise Masking Rollout", "authors": ["Zhuoran Zhao", "Shengju Qian", "Tongtong Liang", "Xianghao Kong", "Songchun Zhang", "Junchao Huang", "Guian Fang", "Xin Wang", "Pan Hui", "Anyi Rao"], "abstract": "Autoregressive (AR) video diffusion models have shown great potential in real-time video generation. Recent methods distill pretrained bidirectional video diffusion models into causal AR students through Distribution Matching Distillation (DMD), but the generated videos often suffer from over-saturation and over-smoothing issues, resulting in limited visual quality and realism. The key contributing factor is the mode-seeking behavior of the reverse KL objective in DMD, which can cause the student distribution to collapse onto only a few modes of the teacher distribution. To address this, we propose Mask Forcing, a Dual-Noise Masking Rollout strategy that perturbs the AR student self-rollout to mitigate mode collapse induced by reverse-KL mode seeking. The core idea is to inject cleaner signals into noisy rollout inputs via random masks along spatial and temporal axes during the self-rollout process of AR diffusion distillation. Such perturbations encourage the student rollouts to explore more regions of the teacher distribution, allowing DMD to provide learning signals beyond the modes already covered by the student. Moreover, the cleaner tokens act as denoising guidance for other noisier tokens, improving the intermediate rollout predictions and reducing error accumulation. Extensive experiments demonstrate that our method improves multiple AR video diffusion distillation methods with higher visual quality efficiently, without incorporating real video data or additional post-training stages.", "published": "2026-09-08", "comment": "Project page: https://alicezrzhao.github.io/mask_forcing/", "url": "https://arxiv.org/abs/2609.09123", "summary": "针对分布匹配蒸馏中反向KL模式寻求致过饱和、过平滑的问题，提出双噪声掩码rollout策略Mask Forcing：在自回滚中沿空间与时间轴随机掩码，把更干净信号注入含噪输入，以缓解模式坍缩并扩大对教师分布的探索，干净token还为更噪token提供去噪引导、减少误差累积。实验显示其提升多种AR蒸馏质量，无需真实视频或额外后训练。"}, {"id": "2609.07915", "title": "JEDI: JEPA-to-Edge Distillation for Efficient Cropland Segmentation from Satellite Imagery", "authors": ["Kishor Kumar Bhaumik", "Nicolas Roque dos Santos", "Jia Chen", "Evangelos E. Papalexakis"], "abstract": "Large vision models provide useful representations for remote-sensing segmentation but are often too expensive for deployment at the satellite or field edge. Existing feature-level distillation methods also tend to assume similar teacher and student architectures and often stop feature alignment when task training begins. We introduce JEDI (JEPA-to-Edge Distillation), a two-stage framework that transfers representations from a large I-JEPA Vision Transformer teacher to a compact SegFormer student. First, JEDI aligns the student's terminal representation with the teacher's token space using cross-architecture projection and spatial alignment. It then jointly optimizes supervised segmentation, temperature-scaled response distillation, and persistent feature alignment throughout task adaptation. On CalCROP21, JEDI-B0 achieves 68.0 mean Intersection-over-Union (mIoU) with 4.04M parameters, improving over the standalone student by 16.0 points and coming within 2.0 points of the 70.0 mIoU achieved by the 639M-parameter teacher. We evaluate SegFormer B0, B1, and B2 students with 4.04M, 14.33M, and 28M parameters, respectively. Across all three variants, JEDI consistently outperforms response-, structure-, channel-, and relational-distillation baselines under the same teacher-student setting. These results show that persistent representation alignment is especially valuable under aggressive compression, substantially reducing model size and computation while preserving segmentation performance.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07915", "summary": "针对大型视觉模型边缘部署过于昂贵、现有蒸馏在任务训练开始后即停止对齐的问题，提出两阶段框架JEDI：先以跨架构投影与空间对齐把学生表征对齐到I-JEPA教师token空间，再联合优化监督分割、响应蒸馏与贯穿训练的特征对齐。CalCROP21上JEDI-B0以4.04M参数达68.0 mIoU，较单独学生提升16.0、距639M教师仅2.0，并在三个学生规模上优于蒸馏基线。"}, {"id": "2609.07328", "title": "PV-WM: A Heterogeneous Micro-Macro World Model for Articulated Pedestrian-Vehicle Co-Rollout", "authors": ["Haozhuang Chi", "Jingsong Liang", "Ziying Song", "Lei Yang", "Shihao Li", "Haoruo Zhang", "Chen Lv"], "abstract": "Local pedestrian-vehicle forecasting spans heterogeneous physical scales: pedestrians combine root locomotion with articulated motion, whereas vehicles are rigid bodies described by kinematic state and oriented extent. Existing road-agent forecasters typically omit pedestrian articulation, while pose forecasters leave vehicle futures outside the learned rollout. We introduce PV-WM, a history-only world model over structured post-perception tracks. It recurrently advances pedestrian root motion, 15-joint articulation, and learned vehicle states within a synchronized heterogeneous state. The generated pedestrian and vehicle chunks supply the next recurrent boundary; vehicle boxes are reconstructed from predicted center and heading with observed extent, and P-V geometry is recomputed after every transition. Relative to a matched one-shot complete-state predictor, recurrent execution reduces Root ADE by 12.7% and MPJPE by 14.8%. Feedback interventions show that later predictions depend on the content, temporal order, and pedestrian identity of generated articulation. Across 824 aligned Waymo contexts, with 797 providing valid future vehicle support, PV-WM reduces Root ADE by 5.2%, MPJPE by 7.6%, P-V distance error by 11.9%, and oriented-box closest-approach error by 5.8% relative to a validation-selected Modular Specialist. The single-network model uses 57.1% fewer parameters, 96.5% lower average FLOPs per local scene, and 25.5% lower measured p95 latency. PV-WM unifies this heterogeneous future state while preserving type-specific pedestrian and vehicle dynamics.", "published": "2026-09-07", "comment": null, "url": "https://arxiv.org/abs/2609.07328", "summary": "针对行人-车辆预测跨异构尺度、现有方法忽略行人铰接或不含车辆的问题，提出仅用历史的结构化世界模型PV-WM：递归推进行人根运动、15关节铰接与车辆状态，每步重建车辆框并重算行人-车辆几何。相对单次完整状态预测，递归执行使Root ADE与MPJPE分别降12.7%和14.8%；824个Waymo上下文上较模块化专家再降多项误差，参数少57.1%、FLOPs低96.5%。"}, {"id": "2609.07216", "title": "The Price of Consistency: Exploiting Visual Anchors for Multimodal Jailbreaking in Video Generation", "authors": ["Peng Li", "Qianqian Xu", "Yangbangyan Jiang", "Zhipeng Yu", "Qingming Huang"], "abstract": "The rapid evolution of video generation has shifted the paradigm from pure text-driven to multi-conditional controllable generation, with reference images now widely adopted as conditional inputs to achieve superior spatiotemporal consistency. While these reference images serve as powerful visual anchors that significantly enhance controllability, their impact on safety remains largely unexplored. In this work, we reveal the visual anchoring effect: by enforcing consistency, the mechanism prevents the generated content from drifting away from the original harmful intent, thereby eliminating the model's natural safety escape route from harmful to benign content. Consequently, visual anchors inherently increase the safety risk---this is the price of consistency. Building on this insight, we propose Decoupling Intent via Visual Anchors (DIVA), a training-free multimodal jailbreak framework for video generation that exploits this vulnerability. DIVA decouples harmful intent into a static visual anchor image and a dynamic motion text prompt, and employs dual-criteria selection to balance attack stealthiness with semantic preservation. Extensive experiments across various leading commercial platforms and mainstream open-source video generation models demonstrate that DIVA achieves a substantially higher Attack Success Rate than existing text-only methods. To facilitate future research, we additionally contribute TI2VSafetyBench, the first safety benchmark for multi-conditional video generation.", "published": "2026-09-07", "comment": "This paper has been accepted to ACM MM 2026", "url": "https://arxiv.org/abs/2609.07216", "summary": "参考图像增强视频生成可控性，但其安全影响未被研究。论文揭示视觉锚定效应：一致性使内容难以偏离有害意图，消除安全逃逸路径。据此提出免训练越狱框架DIVA：把有害意图解耦为视觉锚图像与运动文本提示，以双准则平衡隐蔽性与语义保留。多个商业平台与开源模型上其攻击成功率显著高于纯文本方法，并发布首个多条件视频生成安全基准。"}, {"id": "2609.07135", "title": "NutriBench-Kitchen: Benchmarking Embodied AI for Nutrition Management", "authors": ["Yulin Wei", "Xiangchen Wang", "Jianhui Pan", "Jinyu Xiao", "Zheng Tan", "Ruozai Tian", "Guanhua Chen", "Feng Zheng"], "abstract": "An embodied kitchen assistant must do more than recognize food in isolated frames. It must track ingredient states over time and integrate visual observations with recipe and nutritional knowledge to support constraint-aware decision-making. We formalize this capability as \\emph{Embodied Nutrition Management}: perceiving nutrition-relevant events, maintaining a persistent food state, and using it for knowledge-grounded planning. Existing benchmarks evaluate static food understanding or embodied cooking actions, but do not measure whether an agent can continuously update and use nutrition-relevant states in dynamic kitchens. To fill this gap, we introduce \\textbf{NutriBench-Kitchen}, a benchmark containing 1,500 manually verified question--answer pairs from 160 cooking videos. It covers five task families: Ingredient Entry, Memory Management, Recipe Query, Long-Term Planning, and Short-Term Planning, spanning food-state construction, maintenance, knowledge retrieval, and decision-making across different planning horizons. Evaluations of proprietary and open-source large vision-language models reveal a substantial gap from human performance, particularly in quantitative ingredient estimation, long-term state tracking, and reasoning under interacting constraints. We further introduce \\textbf{Nutri-Vgent}, a diagnostic long-video agent with separate episodic, food-state, and recipe memories. Its consistent improvements demonstrate the value of explicit state representations and structured memory for nutrition management. Together, NutriBench-Kitchen and Nutri-Vgent provide a testbed for studying persistent state tracking and knowledge-grounded reasoning in dynamic kitchens. Code is available at https://github.com/V1ol1n/NutriBench-Kitchen.", "published": "2026-09-07", "comment": "17 pages, 4 figures, ECCV", "url": "https://arxiv.org/abs/2609.07135", "summary": "针对厨房中持续营养状态管理缺乏评测的问题，构建NutriBench-Kitchen：含160段烹饪视频与1500个人工核验问答对，覆盖食材录入、记忆管理、食谱查询与规划等五类任务。专有与开源大视觉语言模型评测显示明显人机差距，尤其定量食材估计与长期追踪；并提出分设情景、食物状态与食谱记忆的agent Nutri-Vgent，其改进体现结构化记忆的价值。"}, {"id": "2609.07126", "title": "Beyond Task Success: Stage-Wise Reliability of World Model Planning under Sensing Degradation", "authors": ["Geonmyeong Lee", "Byoung-Tak Zhang"], "abstract": "In world model planning, sensing inputs pass through an encoder and predictor before affecting planner decisions, so final task success alone cannot reveal where sensing disturbances attenuate or persist in the pipeline. We apply 10 visual and temporal sensing degradations to a world model planner and track their effects across representation, future prediction, planner preference, and physical outcome using paired evaluation on the same 50 tasks. The relative impact of degradations was not preserved across stages: large representation shifts could attenuate downstream, while smaller initial shifts could persist to the outcome, and internal-response ordering did not directly match physical-outcome ordering. Temporal degradations also showed distinct patterns: even with similar overall changes in observation history, responses differed substantially with the location of corrupted information and the planner's actual exposure. This non-uniform stage-wise response was also observed in secondary evaluations with another manipulation task and a different world model. Stage-wise diagnosis can therefore identify where sensing disturbances attenuate or persist and help prioritize subsequent model verification and sensing mitigation.", "published": "2026-09-07", "comment": "8 pages, 3 figures, 2 tables", "url": "https://arxiv.org/abs/2609.07126", "summary": "针对仅凭任务成功无法定位感知扰动影响的问题，对世界模型规划器施加10种视觉与时间退化，在相同50个任务上配对评估表征、预测、规划偏好与物理结果。各阶段影响并不一致：大表征偏移可下游衰减，小偏移可延续到结果，时间退化还随损坏位置而异。分阶段诊断可据此定位扰动影响，指导后续验证与缓解。"}, {"id": "2609.06991", "title": "AV-SafetyBench: A Safety Benchmark for Text-to-Audio-Video Generation", "authors": ["Suah Choi", "Tae-Young Lee", "Gyeong-Moon Park"], "abstract": "Recent text-to-audio-video (T2AV) models jointly generate video, speech, sound effects, and ambience from a single text prompt. This capability poses new challenges for safety evaluation, as unsafe content may be conveyed through the audio track or arise only when the visual and audio tracks are interpreted jointly. Existing safety benchmarks largely focus on either generated video or generated audio in isolation and are therefore not designed to capture these risks. To close this gap, we introduce AV-SafetyBench, the first safety benchmark developed specifically for T2AV generation. AV-SafetyBench comprises a four-axis, 13-category taxonomy and 5,200 manually reviewed prompts that specify visual scenes, speech, and non-speech audio. Our evaluation protocol assesses each output under three views: Full-AV, Video-Only, and Audio-Only. It then uses the Video-Only and Audio-Only judgments to assign Full-AV unsafe outputs to one of four risk sources: Video-Only, Audio-Only, AV-Both, or AV-Joint. We evaluate five open-source T2AV models and validate the automated Full-AV judgments against human annotations. Across the five models, Full-AV Unsafe Rates range from 25.1% to 49.4%. Beyond these aggregate rates, risk-source analysis reveals that, for four of the five models, Audio-Only and AV-Joint cases-unsafe outputs missed by video-only evaluation-account for 41.6-48.3% of Full-AV unsafe outputs for which a risk source could be assigned. In the Cross-Modal Harm Emergence category, AV-Joint accounts for 87.5% of unsafe outputs withan assigned risk source. Together, these findings demonstrate the value of AV-SafetyBench for evaluating T2AV safety across the visual and audio modalities and their interaction.", "published": "2026-09-07", "comment": "34 pages, 19 figures, 17 tables", "url": "https://arxiv.org/abs/2609.06991", "summary": "针对文生音视频模型可能经音频轨或视听联合解读传递不安全内容、现有安全基准仅覆盖单一模态的问题，提出首个T2AV安全基准AV-SafetyBench：含四轴13类分类法与5200条人工审核提示，以Full-AV、Video-Only、Audio-Only三种视角评估并归类风险来源。五个开源模型不安全率为25.1%至49.4%，仅音频与视听联合案例占可归因不安全输出的41.6%至48.3%，凸显跨模态评估的必要。"}, {"id": "2609.09155", "title": "SyncWorld: Visual Calibration Enables World Models as Zero-Shot Simulators", "authors": ["Yuncong Yang", "Zhengtao Han", "Furkan Ozyurt", "Zeyuan Yang", "Han Yang", "Junyi Cao", "Haoyu Zhen", "Yilun Du", "Chuang Gan"], "abstract": "World models are increasingly used as policy-in-the-loop imagination environments, where reliable rollouts require fine-grained controllability with respect to low-level robot actions. A key obstacle to scaling such models in robotics is that actions are not a universal language in pixel space: changes in visual environment, camera view, robot placement, or embodiment alter how the same numerical action manifests visually, leading to conflicting supervision under mixed training and brittle generalization at deployment. We introduce SyncWorld, an action-conditioned world model that serves as a zero-shot simulator across unseen environments without any additional training. SyncWorld leverages a visual calibration episode---paired frames and actions that showcase all the controllable degrees of freedom---to specify the setup-specific Action--Visual Mapping in context. Training with visual calibration contexts teaches the model to interpret actions through visual evidence and to leverage interaction history when explicit calibration is unavailable. Experiments show that SyncWorld can accurately simulate action outcomes in previously unseen settings, and that its capability of simulating rollouts enables test-time policy improvement without training.", "published": "2026-09-08", "comment": null, "url": "https://arxiv.org/abs/2609.09155", "summary": "针对环境或本体变化使同一动作呈现不同视觉表现、致监督冲突与泛化脆弱的问题，提出动作条件世界模型SyncWorld：借助展示可控自由度的标定回合，在上下文指定动作-视觉映射，使模型依视觉证据解释动作、缺标定时利用交互历史。实验显示其能在未见设置中模拟动作结果，并支持免训练的测试时策略改进。"}, {"id": "2609.08796", "title": "Hi-FLoop: Hierarchical State-Feedback Loops for Multi-Timescale World Modeling", "authors": ["Rx Fan", "Zhan H"], "abstract": "Multi-agent traffic simulation seeks diverse, coordinated, and physically realistic futures from maps and observed history. Long-horizon closed-loop generation must reconcile multiple decision time scales while its context evolves with generated states. Existing methods often unfold long futures from the initial scene and resolve intent, interaction, and motion monolithically, weakening cross-scale consistency and adaptation. We present HI-FLOOP, a branch-consistent multi-timescale state-feedback framework. Eight scene-level Worlds represent joint hypotheses, and all agents share the selected World identity throughout an 8-second rollout. Within the branch, an 8-second Goal anchors intent, a 2-second Preview coordinates interactions, and 1-second Control produces physical motion. Every 0.5-second commit feeds back only its executed prefix as new facts, while unexecuted hypotheses never enter factual memory. Joint Preview Interaction (JPI) induces a sparse directed future graph from Preview and uses conflict probabilities and signed arrival-time differences to gate interaction refinement. For generated-state recovery, a prefix-frozen A-to-B cascade lets frozen Model A generate 0-1 seconds, then transfers typed physical state, admissible context, and the branch index, but no latent state, to an independent Model B for re-encoding and 1-2-second recovery. On the full H-D public-validation split of 955 scenarios, one complete S1 run yields an Overall score of 0.689987 with the official evaluator. Under agent-centric oracle evaluation, HI-FLOOP achieves oracle-minADE@8 of 1.196636 m over the 8-second horizon and 0.526 m over the 6-second horizon.", "published": "2026-09-08", "comment": "13 pages, 2 figures, and 6 tables", "url": "https://arxiv.org/abs/2609.08796", "summary": "针对多智能体交通仿真长时程生成的多尺度调和问题，提出分支一致的多时间尺度状态反馈框架Hi-FLoop：八个场景级World表示联合假设，分支内以8秒Goal、2秒Preview、1秒Control分层锚定意图、协调交互与产生运动，每0.5秒仅将已执行前缀反馈为事实，并以冲突概率门控交互细化与级联恢复。H-D公开验证集955场景上Overall达0.689987，8秒oracle-minADE为1.196636米。"}, {"id": "2609.08505", "title": "Temporal State Transport in Video Generation: Diagnosing and Correcting Spectral Imbalance", "authors": ["Luyao Tang", "Bingjun Luo", "Dong Yi", "Jialin Guo", "Haoning Xi", "Cheng Chen", "Yizhou Yu", "Chaoqi Chen"], "abstract": "Reliable video generation requires more than high-quality frames to form a coherent story: a model must maintain a persistent state, transporting visual attributes such as identity, scene layout, motion, and fine details across time. Existing training-free methods mainly strengthen cross-frame attention or analyze local attention entropy, but these views do not reveal whether temporal interactions stay in a healthy transport regime. In this work, we study video generation through the perspective of Temporal State Transport. We introduce Spectral Tension, a signed diagnostic that compares local attention diffuseness with global spectral diversity, and use it to identify two opposite temporal failures: fragmented transport and over-mixing hotspots. Based on this diagnosis, we propose Spectral Transport Homeostasis, a training-free regulator that softly corrects pathological temporal states while largely preserving balanced ones. Experiments on pretrained video generation models show that the original model often occupies imbalanced temporal regimes, whereas our method selectively applies larger corrections to the worst temporal hotspots and improves temporal consistency and visual quality without finetuning. Code: https://github.com/lytang63/temporal-state-transport", "published": "2026-09-08", "comment": "**Best Paper** Award! ICML 2026 F2S Workshop", "url": "https://arxiv.org/abs/2609.08505", "summary": "针对视频生成需跨时间维持持久状态而免训练方法难判时间交互健康的问题，以时间状态传输视角提出诊断量Spectral Tension：比较局部注意力扩散与全局频谱多样性，识别碎片化与过混合两类失败；据此提出免训练调节器Spectral Transport Homeostasis，软纠正病态、保留平衡状态。实验显示模型常处失衡区间，免微调即提升时间一致性与视觉质量。"}, {"id": "2609.08444", "title": "Safe Task Planning with Long-Term Graph Memory for Embodied Agents", "authors": ["Siyuan Li", "Taiyan Lang", "Aoqi Yan", "Jia Yu", "Feifan Liu", "Yihan Du", "Yu Zheng", "Xun Wang", "Peng Liu"], "abstract": "Large language models (LLMs) and vision-language models (VLMs) have significantly advanced zero-shot task planning for embodied agents. However, most LLM- and VLM-driven methods struggle to generate safe high-level actions due to a lack of physical risk awareness, particularly under partial observability, where hazards lie outside the immediate field of view. To address this challenge, we propose a novel safe task-planning framework, SafeMem, which constructs and maintains a long-term semantic graph memory of the open and dynamic environment. Based on egocentric observations, the proposed framework incrementally accumulates knowledge about surrounding objects and their relationships with a graph. Then, an LLM-based risk predictor evaluates candidate actions using the graph memory, triggering a conservatism-modulated replanning loop with explanations for detected hazards. Extensive experiments on the IS-Bench benchmark and a real-world robot platform demonstrate that the SafeMem framework substantially improves safe success rates compared to state-of-the-art VLM-driven task planners. Video results are available on our webpage: https://sites.google.com/view/safemem.", "published": "2026-09-08", "comment": "CoRL 2026", "url": "https://arxiv.org/abs/2609.08444", "summary": "针对LLM与VLM驱动的零样本规划缺乏物理风险意识、部分可观测下危险位于视野之外的问题，提出SafeMem框架：依据自我中心观测增量构建并维护环境的长期语义图记忆，由LLM风险预测器借助图记忆评估候选动作，触发带危险解释的保守度调节重规划循环。IS-Bench与真实机器人平台实验显示，其安全成功率较SOTA VLM规划器显著提升。"}, {"id": "2609.08402", "title": "Towards Embodied Air-Ground Cooperative Object Search: Benchmark, Dataset and Agentic Method", "authors": ["Boao Yu", "Zimo Chen", "Junreng Rao", "Yue Hu", "Zhengqiu Zhu", "Yong Zhao", "Rusheng Ju"], "abstract": "Air-Ground Object Search (AGOS) in urban environments is a challenging embodied task, which requires an Unmanned Aerial Vehicle (UAV) and an Unmanned Ground Vehicle (UGV) to jointly search for and verify a specified target vehicle from multi-view visual references. To study this underexplored problem, we introduce AGOS-Bench, the first dedicated benchmark for evaluating whether general-purpose Vision-Language Models (VLMs) can integrate aerial discoveries and ground-level verification through UAV-UGV cooperation. We further provide AGOS-Dataset as the companion resource of exemplary trajectories constructed by an automatic pipeline. It consists of 7.7k episodes for searching objects of diverse categories and attributes, spanning three difficulty levels. To address the AGOS task, we propose AGOS-Agent, a training-free and tool-augmented approach. The agentic method relieves VLMs from complex and dynamic coordination via a deliberate search-handoff-verify cooperation protocol, only demanding VLMs for scene understanding and decision-making. Extensive experiments on nine VLMs show that AGOS-Agent improves overall success rate for eight of the nine evaluated backbones while reducing decision steps for all nine. On the hard split, the SR and SPL of Gemini-3.6-Flash increase from 8.6% to 55.7% and from 7.6% to 44.0%, respectively.", "published": "2026-09-08", "comment": "16 pages, 4 figures, 4 tables; includes an appendix", "url": "https://arxiv.org/abs/2609.08402", "summary": "针对城市环境下无人机与地面车协同搜索并验证目标车辆的空地目标搜索任务，构建首个基准AGOS-Bench与自动流程生成的AGOS-Dataset（7.7k示范轨迹、三个难度级），并提出免训练、工具增强的AGOS-Agent：以搜索-交接-验证协议分解协调，VLM只承担场景理解与决策。九个VLM上八个整体成功率提升、九个决策步数均减少；困难划分上Gemini-3.6-Flash成功率从8.6%升至55.7%。"}]}}};
